    "terms.section1_title": "1. Servicio",
    "terms.section1_body": "Jandosoft proporciona una plataforma de herramientas cloud, CRM, IA y gestión empresarial. El uso de la plataforma está sujeto a los presentes términos.",
    "terms.section2_title": "2. Cuentas",
    "terms.section2_body": "El usuario es responsable de mantener la confidencialidad de sus credenciales. Jandosoft no será responsable por accesos no autorizados derivados del mal uso de las credenciales.",
    "terms.section3_title": "3. Limitación de Responsabilidad",
    "terms.section3_body": "Jandosoft proporciona el servicio \"tal cual\". No garantizamos que el servicio sea ininterrumpido o libre de errores. En ningún caso Jandosoft será responsable por daños indirectos, pérdida de datos, pérdida de ingresos o interrupción del negocio derivados del uso o la imposibilidad de uso de la plataforma. Nuestra responsabilidad máxima se limita al monto pagado por el servicio en los últimos 12 meses.",
    "terms.section4_title": "4. Datos",
    "terms.section4_body": "Los datos almacenados en la plataforma son propiedad del usuario. Jandosoft no compartirá información personal con terceros sin consentimiento explícito. El usuario es responsable de la veracidad de los datos ingresados.",
    "terms.section5_title": "5. Suscripciones",
    "terms.section5_body": "Las suscripciones se renuevan automáticamente. El usuario puede cancelar en cualquier momento. No se realizan reembolsos por meses parciales. Jandosoft se reserva el derecho de modificar los precios con aviso previo de 30 días.",
    "terms.section6_title": "6. Suspensión",
