    "terms.title": "服务条款和条件",
    "terms.updated": "最后更新：2026年5月",
    "terms.section1_title": "1. 服务",
    "terms.section1_body": "Jandosoft提供云工具、CRM、AI和业务管理平台。使用本平台即表示接受以下条款。",
    "terms.section2_title": "2. 账户",
    "terms.section2_body": "用户有责任维护其凭据的机密性。Jandosoft对因凭据使用不当导致的未授权访问不承担责任。",
    "terms.section3_title": "3. 责任限制",
    "terms.section3_body": "Jandosoft按\"现状\"提供服务。我们不保证服务不会中断或没有错误。在任何情况下，Jandosoft均不对因使用或无法使用平台而导致的间接损害、数据丢失、收入损失或业务中断承担责任。我们的最大责任限于过去12个月内为服务支付的金额。",
    "terms.section4_title": "4. 数据",
    "terms.section4_body": "平台上存储的数据归用户所有。未经明确同意，Jandosoft不会与第三方共享个人信息。用户对所输入数据的准确性负责。",
    "terms.section5_title": "5. 订阅",
    "terms.section5_body": "订阅将自动续订。用户可以随时取消。部分月份不予退款。Jandosoft保留提前30天通知修改价格的权利。",
    "terms.section6_title": "6. 暂停",
    "terms.section6_body": "Jandosoft保留暂停违反这些条款、用于非法活动或对平台或其用户构成风险的账户的权利。",
    "terms.section7_title": "7. 联系方式",
    "terms.section7_body": "如有任何法律或支持问题，请通过平台上的AI聊天或电子邮件联系我们。",
